use ingetrazo_gui::IngeTrazoApp;
fn main(){let dir=std::path::PathBuf::from(std::env::args().nth(1).unwrap());std::fs::create_dir_all(&dir).unwrap();let mut app=IngeTrazoApp::new();app.scene.mesh.add_vertex(glam::DVec3::new(9.,8.,7.));app.save_undo_state();app.scene.mesh.add_vertex(glam::DVec3::X);app.undo();let current=dir.join("existing-model.igz");std::fs::write(&current,b"retained destination bytes").unwrap();app.current_file=Some(current.clone());let mut checks=vec![];for (name,bytes,empty) in [("bad.kmz",&b"not a zip"[..],false),("bad-schema.geojson",&b"{\"type\":\"LineString\",\"coordinates\":[[1,2],[3,\"bad\"]]}"[..],false),("empty.geojson",&b"{\"type\":\"FeatureCollection\",\"features\":[]}"[..],true)]{let path=dir.join(name);std::fs::write(&path,bytes).unwrap();let scene=app.scene.clone();let camera=app.camera.clone();let undo=app.undo_stack.clone();let redo=app.redo_stack.clone();let result=app.import_geographic_paths(&path);if empty{assert_eq!(result.unwrap(),0)}else{assert!(result.is_err())}assert_eq!(app.scene,scene);assert_eq!(app.camera,camera);assert_eq!(app.undo_stack,undo);assert_eq!(app.redo_stack,redo);assert_eq!(app.current_file.as_ref(),Some(&current));assert_eq!(std::fs::read(&current).unwrap(),b"retained destination bytes");checks.push(name);}println!("{}",serde_json::json!({"atomic_cases":checks,"existing_model_destination_preserved":true,"undone_branch_preserved":true}));}
